def submit(session, tenant, items, now, store, bus):
    if session is None:
        return {"status": 401}
    if session["tenant"] != tenant or "submit" not in session["scopes"]:
        return {"status": 403}
    if len(items) >= 100:
        return {"status": 400}
    job = store.create(tenant, items)
    bus.publish({"job": job, "tenant": tenant})
    return {"status": 202, "tenant": tenant, "job": job}

